if($_SERVER['REQUEST_METHOD']==='POST')try{
 verifyCsrf();$action=(string)($_POST['action']??'');
 if($action==='policy'&&$admin){$newPolicy=(string)($_POST['policy']??'');mfaSavePolicy($newPolicy);try{recordActivity(activityDb(),$user,'mfa-beleid-gewijzigd','beveiliging','instelling','mfa_policy',$newPolicy);}catch(Throwable $ignored){}$message='De MFA-instelling is opgeslagen.';}
 elseif($action==='begin'){if(mfaPolicy()==='off')throw new InvalidArgumentException('MFA staat uit voor deze installatie. De beheerder moet dit eerst inschakelen.');$secret=mfaNewSecret();$_SESSION['mfa_setup_secret']=$secret;$_SESSION['mfa_setup_at']=time();$message='Voer de sleutel handmatig in en bevestig met een actuele code.';}
 elseif($action==='confirm'){if(mfaPolicy()==='off')throw new InvalidArgumentException('MFA staat uit voor deze installatie. De beheerder moet dit eerst inschakelen.');$secret=(string)($_SESSION['mfa_setup_secret']??'');if($secret===''||(int)($_SESSION['mfa_setup_at']??0)<time()-600)throw new InvalidArgumentException('De installatiecode is verlopen; begin opnieuw.');if(!mfaCodeValid($secret,(string)($_POST['code']??'')))throw new InvalidArgumentException('De code klopt niet. Controleer de tijd op uw telefoon.');$codes=mfaIssueRecoveryCodes();$users[$username]['mfa_secret']=mfaEncrypt($secret);$users[$username]['mfa_recovery_hashes']=array_map(static fn($c)=>password_hash($c,PASSWORD_DEFAULT),$codes);saveUsers($users);try{recordActivity(activityDb(),$user,'mfa-ingeschakeld','beveiliging','gebruiker',$username,'TOTP ingesteld');}catch(Throwable $ignored){}unset($_SESSION['mfa_setup_secret'],$_SESSION['mfa_setup_at']);$_SESSION['mfa_recovery_once']=$codes;$message='MFA is ingesteld. Bewaar de herstelcodes op een veilige plek.';$account=$users[$username];}
